INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q1140266', 'Battle of Elmina', 'The Battle of Elmina was a military engagement of the Dutch-Portuguese War, fought near the castle of São Jorge da Mina (Elmina Castle) in the Portuguese Gold Coast in 1625. It was fought between 1,200 soldiers of the Dutch West India Company (transported by a fleet of 15 ships) who landed and assaulted the Portuguese garrison of the castle.', 1625, 10, 25, NULL, NULL, NULL, 'day', '25 October 1625', 48, 'https://en.wikipedia.org/wiki/Battle_of_Elmina_(1625)'),
  ('Q4870293', 'Battle of Amoaful', 'The Battle of Amoaful was fought on 31 January 1874 during the Third Anglo-Ashanti War when Sir Garnet Wolseley defeated the Ashantis after strong resistance. The attack was led by the 42nd Regiment of Foot.', 1874, 1, 31, NULL, NULL, NULL, 'day', '31 January 1874', 34, 'https://en.wikipedia.org/wiki/Battle_of_Amoaful'),
  ('Q98098865', 'Treaty of Fomena', 'Treaty of Fomena was a peace treaty between the Ashanti Empire (in the time of Kofi Karikari) and the British and was formed to end the Third Anglo-Ashanti War. It was formed sometime in February of 1874.', 1874, 2, NULL, NULL, NULL, NULL, 'month', 'February 1874', 26, 'https://en.wikipedia.org/wiki/Treaty_of_Fomena'),
  ('Q2887801', 'Adibo dali', 'The Battle of Adibo was a German military campaign in 1896 against the Dagbamba of West Africa in Adibo, now in present-day Ghana. Following their resistance against foreign authority, the Dagbamba tribesmen met and launched an attack on the heavily armed German Schutztruppe and Askari paramilitary police accompanying the Lieutenant Valentin von Massow on his way to their capital at the village of Adibo, who had been sent by the German colonial administration to quell the rebellion.', 1896, 12, 4, NULL, NULL, NULL, 'day', '4 December 1896', 34, 'https://en.wikipedia.org/wiki/Battle_of_Adibo'),
  ('Q512700', 'Togoland campaign', 'The Togoland campaign (6–26 August 1914) was a French and British invasion of the German colony of Togoland in West Africa, which began the West African campaign of the First World War. German colonial forces withdrew from the capital Lomé and the coastal province to fight delaying actions on the route north to Kamina, where the Kamina Funkstation (wireless transmitter) linked the government in Berlin to Togoland, the Atlantic and South America.', 1914, 8, 9, 1914, 8, 26, 'day', '9 August 1914 – 26 August 1914', 55, 'https://en.wikipedia.org/wiki/Togoland_campaign'),
  ('Q52705852', '1966 Ghanaian coup d''état', 'The 1966 Ghanaian coup d''état (codenamed Operation Cold Chop) was a military overthrow of President Kwame Nkrumah on February 24, 1966, while he was visiting China. The swift coup led to the establishment of an eight-member National Liberation Council (NLC), comprising four army and four police officers.', 1966, 2, 24, NULL, NULL, NULL, 'day', '24 February 1966', 34, 'https://en.wikipedia.org/wiki/1966_Ghanaian_coup_d''%C3%A9tat'),
  ('Q7097104', 'Operation Guitar Boy', 'Operation Guitar Boy was the code-name for an attempted coup d''état on 17 April 1967 in Ghana, by a group of junior officers of the Ghana Armed Forces. Although unsuccessful, the coup resulted in the assassination of Lieutenant General Emmanuel Kwasi Kotoka, Ghana''s Chief of the Defence Staff.', 1967, 4, 17, NULL, NULL, NULL, 'day', '17 April 1967', 26, 'https://en.wikipedia.org/wiki/Operation_Guitar_Boy'),
  ('Q2616916', 'Allied Air Flight 111', 'Allied Air Flight 111 was a cargo flight operated by Lagos-based cargo airliner Allied Air, flying from Lagos, Nigeria to Accra, Ghana. The flight was operated with a Boeing 727 cargo aircraft.', 2012, 6, 2, NULL, NULL, NULL, 'day', '2 June 2012', 50, 'https://en.wikipedia.org/wiki/Allied_Air_Flight_111'),
  ('Q20051820', '2015 Accra floods', 'The 2015 Accra floods resulted from heavy continuous rainfall in Accra, the largest city in Ghana. The rain started on 1 June 2015.', 2015, NULL, NULL, NULL, NULL, NULL, 'year', '2015', 43, 'https://en.wikipedia.org/wiki/2015_Accra_floods'),
  ('Q24890108', '2016 Accra floods', 'The 2016 Accra floods were heavy rainfalls in Accra, the capital of Ghana in June 2016. The flood began on June 9, 2016.', 2016, 6, 9, NULL, NULL, NULL, 'day', '9 June 2016', 39, 'https://en.wikipedia.org/wiki/2016_Accra_floods'),
  ('Q104856693', '2020 African Sahel floods', 'In all of 2020, flooding affected 2.7 million people in 18 countries in West and Central Africa and destroyed 197,000 houses, with many regions recording excess rainfalls. The number of flood-affected people this year was more than twice the case in 2019.', 2020, 8, NULL, 2020, 9, NULL, 'month', 'August 2020 – September 2020', 37, 'https://en.wikipedia.org/wiki/2020_African_Sahel_floods'),
  ('Q110629011', '2022 Bogoso explosion', 'On 20 January 2022, a large explosion occurred in Apiate, a suburban community near Bogoso in the Western Region of Ghana, after a truck transporting mining explosives collided with a motorcycle. The explosion leveled the community, killing 13 people and injuring 200.', 2022, 1, 20, NULL, NULL, NULL, 'day', '20 January 2022', 45, 'https://en.wikipedia.org/wiki/2022_Bogoso_explosion'),
  ('Q124448684', 'Floods in Ghana', 'Floods in Ghana refer to a series of flood incidents that have caused property damage and loss of life. Floods are caused by excessive rainfall and dam spillages.', 2023, NULL, NULL, NULL, NULL, NULL, 'year', '2023', 34, 'https://en.wikipedia.org/wiki/Floods_in_Ghana'),
  ('Q126961247', '2024 West African floods', 'In 2024, heavy rainfall impacted several countries across West and Central Africa, including Nigeria, Chad, Niger, Mali, Guinea, Cameroon and Ghana. At least 1,500 were killed and more than a million were displaced.', 2024, NULL, NULL, NULL, NULL, NULL, 'year', '2024', 37, 'https://en.wikipedia.org/wiki/2024_West_African_floods');
